const getDashboardPath = () => {
  if (!currentUser) return '/';
  switch (currentUser.role) {
    case 'admin':
      return '/admin';
    case 'institution':
      return '/institution-dashboard'; // Updated
    case 'company':
      return '/company-dashboard'; // Updated
    case 'student':
    default:
      return '/dashboard'; // This uses the new Dashboard component
  }
};
